5	namespace App\Modules\Pricing\Domain\Services;
6	
7	use App\Modules\Pricing\Domain\Enums\FloorBasis;
8	use App\Modules\Pricing\Domain\Enums\PriceBasis;
9	use App\Shared\Contracts\CurrencyScaleResolverInterface;
10	use App\Shared\Contracts\DiscountPolicyInterface;
11	use App\Shared\Contracts\DiscountPolicySubjectProviderInterface;
12	use App\Shared\Domain\CurrencyScale;
13	use App\Shared\DTOs\DiscountPolicyContext;
14	use App\Shared\DTOs\DiscountPolicyLineContext;
15	use App\Shared\DTOs\DiscountPolicySubject;
16	use App\Shared\DTOs\DiscountPolicyVerdict;
17	use InvalidArgumentException;
18	
19	final class DiscountPolicyService implements DiscountPolicyInterface
20	{
21	    private const PERMISSION_BELOW_COST = 'pricing.sell_below_cost';
22	
23	    private const PERMISSION_BELOW_MINIMUM_MARGIN = 'pricing.sell_below_minimum_margin';
24	
25	    private const PERCENT_SCALE = 2;
26	
27	    public function __construct(
28	        private readonly DiscountPolicySubjectProviderInterface $subjects,
29	        private readonly DiscountCapResolver $capResolver,
30	        private readonly CurrencyScaleResolverInterface $scaleResolver,
31	    ) {}
32	
33	    public function resolve(DiscountPolicyContext $context): DiscountPolicyVerdict
34	    {
35	        return $this->resolveMany(['line' => $context])['line'];
36	    }
37	
38	    public function resolveMany(array $contexts): array
39	    {
40	        if ($contexts === []) {
41	            return [];
42	        }
43	
44	        $companyId = $this->singleCompanyId($contexts);
45	        $lineContexts = [];
46	        foreach ($contexts as $key => $context) {
47	            $lineContexts[$key] = new DiscountPolicyLineContext(
48	                productId: $context->productId,
49	                variantId: $context->variantId,
50	            );
51	        }
52	
53	        $subjects = $this->subjects->resolveMany($companyId, $lineContexts);
54	
55	        $verdicts = [];
56	        foreach ($contexts as $key => $context) {
57	            $subject = $subjects[$key] ?? null;
58	            if (! $subject instanceof DiscountPolicySubject) {
59	                throw new InvalidArgumentException("No discount policy subject resolved for line {$key}.");
60	            }
61	
62	            $verdicts[$key] = $this->resolveForSubject($context, $subject);
63	        }
64	
65	        return $verdicts;
66	    }
67	
68	    /**
69	     * @param  array<string, DiscountPolicyContext>  $contexts
70	     */
71	    private function singleCompanyId(array $contexts): string
72	    {
73	        $companyIds = [];
74	        foreach ($contexts as $context) {
75	            $companyIds[$context->companyId] = true;
76	        }
77	
78	        if (count($companyIds) !== 1) {
79	            throw new InvalidArgumentException('Discount policy batch resolution requires a single company.');
80	        }
81	
82	        return array_key_first($companyIds);
83	    }
84	
85	    private function resolveForSubject(DiscountPolicyContext $context, DiscountPolicySubject $subject): DiscountPolicyVerdict
86	    {
87	        $scale = $this->scaleResolver->getScale($context->currency);
88	        $effectiveNet = $this->effectiveNetPrice($context, $subject, $scale);
89	        $maxDiscountPercent = $this->capResolver->resolve($subject);
90	        $discountPercent = $this->discountPercent($subject, $effectiveNet);
91	        $contributions = $this->floorContributions($subject, $maxDiscountPercent, $scale);
92	        $winner = $this->winningContribution($contributions, $scale);
93	        $floorPriceNet = $winner['floor'];
94	        $floorBasis = $winner['basis'];
95	        $reasons = [];
96	        $requiresPermission = null;
97	
98	        $wacNet = $this->positiveNumericOrNull($subject->wacNet, $scale);
99	        $belowCost = $wacNet !== null
100	            && bccomp($effectiveNet, CurrencyScale::bcround($wacNet, $scale), $scale) < 0;
101	        $belowFloor = $floorPriceNet !== null && bccomp($effectiveNet, $floorPriceNet, $scale) < 0;
102	
103	        if ($belowCost) {
104	            $reasons[] = 'below_cost';
105	            $requiresPermission = self::PERMISSION_BELOW_COST;
106	        }
107	
108	        if ($belowFloor) {
109	            $reasons[] = $floorBasis === FloorBasis::DiscountCap->value ? 'discount_cap' : 'minimum_margin_floor';
110	            $requiresPermission ??= self::PERMISSION_BELOW_MINIMUM_MARGIN;
111	        }
112	
113	        $blocksSale = $requiresPermission !== null && $subject->discountFloorMode === 'Block';
114	        $severity = $blocksSale ? 'block' : ($requiresPermission !== null ? 'warn' : 'ok');
115	
116	        return new DiscountPolicyVerdict(
117	            allowed: ! $blocksSale,
118	            blocksSale: $blocksSale,
119	            severity: $severity,
120	            requiresPermission: $requiresPermission,
121	            maxDiscountPercent: $maxDiscountPercent,
122	            discountPercent: $discountPercent,
123	            floorPriceNet: $floorPriceNet,
124	            floorBasis: $floorBasis,
125	            floorEnforcement: $subject->discountFloorMode,
126	            mode: $subject->discountFloorMode,
127	            overridable: $requiresPermission !== null,
128	            requiresReason: false,
129	            policyVersion: $subject->policyVersion,
130	            policyAsOf: $subject->policyAsOf,
131	            reasons: array_values(array_unique($reasons)),
132	            meta: [
133	                'effectiveUnitPriceNet' => $effectiveNet,
134	                'priceBasis' => $context->priceBasis,
135	                'currency' => $context->currency,
136	            ],
137	        );
138	    }
139	
140	    /**
141	     * @return array<int, array{basis: string, floor: numeric-string}>
142	     */
143	    private function floorContributions(DiscountPolicySubject $subject, string $maxDiscountPercent, int $scale): array
144	    {
145	        $contributions = [];
146	        $wacNet = $this->positiveNumericOrNull($subject->wacNet, $scale);
147	
148	        if ($wacNet !== null) {
149	            $costFloor = CurrencyScale::bcround($wacNet, $scale);
150	            $contributions[] = ['basis' => FloorBasis::Cost->value, 'floor' => $costFloor];
151	
152	            $minimumMarginPercent = $this->positiveNumericOrNull($subject->minimumMarginPercent, self::PERCENT_SCALE);
153	            if ($minimumMarginPercent !== null) {
154	                $intermediate = $scale + 4;
155	                $factor = bcadd('1', bcdiv($minimumMarginPercent, '100', $intermediate), $intermediate);
156	                $contributions[] = [
157	                    'basis' => FloorBasis::MinimumMargin->value,
158	                    'floor' => CurrencyScale::bcround(bcmul($wacNet, $factor, $intermediate), $scale),
159	                ];
160	            }
161	        }
162	
163	        $salePriceNet = $this->positiveNumericOrNull($subject->salePriceNet, $scale);
164	        $maxDiscountPercent = $this->numericString($maxDiscountPercent);
165	        if (
166	            $salePriceNet !== null
167	            && bccomp($maxDiscountPercent, '100.00', self::PERCENT_SCALE) < 0
168	        ) {
169	            $intermediate = $scale + 4;
170	            $factor = bcsub('1', bcdiv($maxDiscountPercent, '100', $intermediate), $intermediate);
171	            $contributions[] = [
172	                'basis' => FloorBasis::DiscountCap->value,
173	                'floor' => CurrencyScale::bcround(bcmul($salePriceNet, $factor, $intermediate), $scale),
174	            ];
175	        }
176	
177	        return $contributions;
178	    }
179	
180	    /**
181	     * @param  array<int, array{basis: string, floor: numeric-string}>  $contributions
182	     * @return array{basis: string, floor: numeric-string|null}
183	     */
184	    private function winningContribution(array $contributions, int $scale): array
185	    {
186	        $winner = ['basis' => FloorBasis::None->value, 'floor' => null];
187	
188	        foreach ($contributions as $contribution) {
189	            if (
190	                $winner['floor'] === null
191	                || bccomp($contribution['floor'], $winner['floor'], $scale) > 0
192	            ) {
193	                $winner = $contribution;
194	            }
195	        }
196	
197	        return $winner;
198	    }
199	
200	    /**
201	     * @return numeric-string
202	     */
203	    private function effectiveNetPrice(DiscountPolicyContext $context, DiscountPolicySubject $subject, int $scale): string
204	    {
205	        $price = CurrencyScale::bcformatStrict($context->effectiveUnitPrice, $scale + 4);
206	
207	        if ($context->priceBasis !== PriceBasis::Ttc->value) {
208	            return CurrencyScale::bcround($price, $scale);
209	        }
210	
211	        $taxRate = $context->taxRate ?? $subject->resolvedTaxRate;
212	        $taxRate = $this->numericString($taxRate);
213	        $factor = bcadd('1', bcdiv($taxRate, '100', $scale + 4), $scale + 4);
214	
215	        return CurrencyScale::bcround(bcdiv($price, $factor, $scale + 4), $scale);
216	    }
217	
218	    private function discountPercent(DiscountPolicySubject $subject, string $effectiveNet): ?string
219	    {
220	        $salePriceNet = $this->positiveNumericOrNull($subject->salePriceNet, self::PERCENT_SCALE);
221	        if ($salePriceNet === null) {
222	            return null;
223	        }
224	
225	        $intermediate = 6;
226	        $effectiveNet = $this->numericString($effectiveNet);
227	        $discount = bcsub($salePriceNet, $effectiveNet, $intermediate);
228	        $percent = bcmul(bcdiv($discount, $salePriceNet, $intermediate), '100', $intermediate);
229	
230	        return CurrencyScale::bcround($percent, self::PERCENT_SCALE);
231	    }
232	
233	    /**
234	     * @return numeric-string|null
235	     */
236	    private function positiveNumericOrNull(?string $value, int $scale): ?string
237	    {
238	        $numeric = $this->numericOrNull($value);
239	
240	        if ($numeric === null || bccomp($numeric, '0', $scale + 2) <= 0) {
241	            return null;
242	        }
243	
244	        return $numeric;
245	    }
246	
247	    /**
248	     * @return numeric-string|null
249	     */
250	    private function numericOrNull(?string $value): ?string
251	    {
252	        if ($value === null) {
253	            return null;
254	        }
255	
256	        return $this->numericString($value);
257	    }
258	
259	    /**
260	     * @return numeric-string
261	     */
262	    private function numericString(string $value): string
263	    {
264	        if (! is_numeric($value)) {
265	            throw new InvalidArgumentException("Discount policy numeric value '{$value}' is invalid.");
266	        }
267	
268	        return $value;
269	    }
270	}
