5	namespace App\Modules\Product\Application\Services;
6	
7	use App\Modules\Product\Domain\Category;
8	use App\Modules\Product\Domain\Product;
9	use App\Shared\Contracts\DiscountPolicySubjectProviderInterface;
10	use App\Shared\Contracts\TaxConfigurationLookupInterface;
11	use App\Shared\DTOs\DiscountPolicyLineContext;
12	use App\Shared\DTOs\DiscountPolicySubject;
13	use App\Shared\DTOs\TaxConfigurationSummary;
14	use Illuminate\Database\Eloquent\Collection as EloquentCollection;
15	use Illuminate\Support\Collection;
16	use RuntimeException;
17	
18	final class DiscountPolicySubjectProvider implements DiscountPolicySubjectProviderInterface
19	{
20	    public function __construct(
21	        private readonly MarginResolver $marginResolver,
22	        private readonly TaxConfigurationLookupInterface $taxConfigurations,
23	    ) {}
24	
25	    /**
26	     * @param  array<string, DiscountPolicyLineContext>  $contexts
27	     * @return array<string, DiscountPolicySubject>
28	     */
29	    public function resolveMany(string $companyId, array $contexts): array
30	    {
31	        $productIds = collect($contexts)
32	            ->map(fn (DiscountPolicyLineContext $context): string => $context->productId)
33	            ->unique()
34	            ->values()
35	            ->all();
36	
37	        /** @var EloquentCollection<int, Product> $products */
38	        $products = Product::query()
39	            ->where('company_id', $companyId)
40	            ->whereIn('id', $productIds)
41	            ->with(['company', 'category'])
42	            ->get();
43	
44	        /** @var Collection<string, Product> $productsById */
45	        $productsById = $products->keyBy('id');
46	        $marginsByProductId = $this->marginResolver->resolveMany($products);
47	        $categoriesById = $this->loadCategoryAncestors($products);
48	        $taxConfigurationsById = $this->loadTaxConfigurations($products, $categoriesById);
49	        $policyAsOf = now()->toIso8601String();
50	
51	        $subjects = [];
52	        foreach ($contexts as $lineKey => $context) {
53	            $product = $productsById->get($context->productId);
54	            if (! $product instanceof Product) {
55	                throw new RuntimeException("Product {$context->productId} was not found for discount policy resolution.");
56	            }
57	
58	            $company = $product->company;
59	            $category = $product->category;
60	            $categoryCaps = $this->categoryCapsNearestFirst($product, $categoriesById);
61	            $taxConfigurationId = $product->default_tax_configuration_id
62	                ?? ($category instanceof Category ? $category->default_tax_configuration_id : null)
63	                ?? $company->default_tax_configuration_id;
64	            $taxConfiguration = $taxConfigurationId !== null ? $taxConfigurationsById->get($taxConfigurationId) : null;
65	            $resolvedTaxRate = $taxConfiguration instanceof TaxConfigurationSummary
66	                ? (string) ($taxConfiguration->percentageRate ?? '0.00')
67	                : (string) ($product->tax_rate ?? ($category instanceof Category ? $category->default_tax_rate : null) ?? $company->default_tax_rate ?? '0.00');
68	
69	            $subjects[$lineKey] = DiscountPolicySubject::make(
70	                companyId: $company->id,
71	                productId: $product->id,
72	                variantId: $context->variantId,
73	                productMaxDiscountPercent: $product->max_discount_percent !== null ? (string) $product->max_discount_percent : null,
74	                categoryMaxDiscountPercents: $categoryCaps,
75	                companyMaxDiscountPercent: $company->default_max_discount_percent !== null ? (string) $company->default_max_discount_percent : null,
76	                salePriceNet: $product->sale_price !== null ? (string) $product->sale_price : null,
77	                wacNet: (string) $product->cost_price,
78	                lastPurchaseCost: $product->last_purchase_cost !== null ? (string) $product->last_purchase_cost : null,
79	                minimumMarginPercent: $marginsByProductId[$product->id]->minimum_margin,
80	                currency: $company->currency,
81	                taxConfigurationId: $taxConfigurationId,
82	                taxRate: $product->tax_rate !== null ? (string) $product->tax_rate : null,
83	                resolvedTaxRate: $resolvedTaxRate,
84	                discountFloorMode: $company->discount_floor_mode->value,
85	                priceEntryMode: $company->price_entry_mode->value,
86	                policyAsOf: $policyAsOf,
87	            );
88	        }
89	
90	        return $subjects;
91	    }
92	
93	    public function resolve(string $companyId, string $productId, ?string $variantId = null): DiscountPolicySubject
94	    {
95	        return $this->resolveMany($companyId, [
96	            'single' => new DiscountPolicyLineContext(productId: $productId, variantId: $variantId),
97	        ])['single'];
98	    }
99	
100	    /**
101	     * @param  EloquentCollection<int, Product>  $products
102	     * @return Collection<int, Category>
103	     */
104	    private function loadCategoryAncestors(EloquentCollection $products): Collection
105	    {
106	        $categoryIds = $products
107	            ->map(fn (Product $product): ?Category => $product->category)
108	            ->filter()
109	            ->flatMap(fn (Category $category): array => explode('/', $category->path))
110	            ->filter(fn (string $id): bool => $id !== '')
111	            ->map(fn (string $id): int => (int) $id)
112	            ->unique()
113	            ->values()
114	            ->all();
115	
116	        if ($categoryIds === []) {
117	            return collect();
118	        }
119	
120	        return Category::query()
121	            ->whereIn('id', $categoryIds)
122	            ->get()
123	            ->keyBy('id');
124	    }
125	
126	    /**
127	     * @param  Collection<int, Category>  $categoriesById
128	     * @return array<int, string|null>
129	     */
130	    private function categoryCapsNearestFirst(Product $product, Collection $categoriesById): array
131	    {
132	        if ($product->category === null) {
133	            return [];
134	        }
135	
136	        $caps = [];
137	        foreach (array_reverse(explode('/', $product->category->path)) as $id) {
138	            if ($id === '') {
139	                continue;
140	            }
141	
142	            $category = $categoriesById->get((int) $id);
143	            if ($category instanceof Category) {
144	                $caps[] = $category->max_discount_percent !== null ? (string) $category->max_discount_percent : null;
145	            }
146	        }
147	
148	        return $caps;
149	    }
150	
151	    /**
152	     * @param  EloquentCollection<int, Product>  $products
153	     * @param  Collection<int, Category>  $categoriesById
154	     * @return Collection<string, TaxConfigurationSummary>
155	     */
156	    private function loadTaxConfigurations(EloquentCollection $products, Collection $categoriesById): Collection
157	    {
158	        $taxConfigurationIds = $products
159	            ->flatMap(function (Product $product) use ($categoriesById): array {
160	                $ids = [
161	                    $product->default_tax_configuration_id,
162	                    $product->company->default_tax_configuration_id,
163	                ];
164	
165	                if ($product->category !== null) {
166	                    foreach (explode('/', $product->category->path) as $categoryId) {
167	                        $category = $categoriesById->get((int) $categoryId);
168	                        if ($category instanceof Category) {
169	                            $ids[] = $category->default_tax_configuration_id;
170	                        }
171	                    }
172	                }
173	
174	                return $ids;
175	            })
176	            ->filter()
177	            ->unique()
178	            ->values()
179	            ->all();
180	
181	        if ($taxConfigurationIds === []) {
182	            return collect();
183	        }
184	
185	        return collect($this->taxConfigurations->findManyById($taxConfigurationIds));
186	    }
187	}
