    }

    // ((sell - cost) / cost) * 100
    $diff = bcsub($sellStr, $costStr, $inter + 2);
    $ratio = bcdiv($diff, $costStr, $inter + 2);
    $percent = bcmul($ratio, '100', $inter + 2);

    return (float) $this->bcRoundHalfUp($percent, self::MARGIN_SCALE);
}

